{
  "application": "myapp",
  "name": "parameterized-pipeline",
  "parameterConfig": [
    {
      "name": "environment",
      "label": "Environment",
      "required": true,
      "default": "dev",
      "description": "Target environment",
      "options": [
        {"value": "dev"},
        {"value": "staging"},
        {"value": "prod"}
      ]
    },
    {
      "name": "version",
      "label": "Version",
      "required": true,
      "default": "1.0.0",
      "description": "Version to deploy"
    }
  ],
  "stages": [
    {
      "type": "wait",
      "name": "Deploy to ${parameters.environment}",
      "refId": "1",
      "waitTime": 30
    }
  ]
}
